/** Actual server GameMode block activation; GUI opening is captured without a fake network transport. */
final class ProgrammerInteractionChecks {
 private static int checks;
 private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Programmer interaction: "+why);}
 private static final class Actor extends net.neoforged.neoforge.common.util.FakePlayer{
  int opened;BlockPos menuPos;
  Actor(ServerLevel level){super(level,new com.mojang.authlib.GameProfile(new UUID(0,592),"ProgrammerUse"));}
  @Override public OptionalInt openMenu(MenuProvider provider,java.util.function.Consumer<RegistryFriendlyByteBuf> data){var buffer=new RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),serverLevel().registryAccess());try{data.accept(buffer);menuPos=buffer.readBlockPos();need(!buffer.isReadable(),"bounded menu open position");}finally{buffer.release();}containerMenu=provider.createMenu(++opened,getInventory(),this);return OptionalInt.of(opened);}
 }
 private static Vec3 point(JsonArray a){return new Vec3(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble());}
 private static BlockHitResult aim(Actor actor,ServerLevel world,NativeProgrammerBlock block,BlockPos root,Direction facing,int slot,List<JsonObject> rows){for(var row:rows){if(!row.has("hit")||!row.get("facing").getAsString().equals(facing.name())||row.get("slot").getAsInt()!=slot)continue;Vec3 shift=new Vec3(root.getX()-7,root.getY()-80,root.getZ()+11),eye=point(row.getAsJsonArray("from")).add(shift),end=point(row.getAsJsonArray("to")).add(shift),direction=end.subtract(eye).normalize();actor.setPos(eye.x,eye.y-actor.getEyeHeight(),eye.z);actor.setYRot((float)Math.toDegrees(Math.atan2(-direction.x,direction.z)));actor.setXRot((float)-Math.toDegrees(Math.asin(direction.y)));var actual=world.clip(new ClipContext(actor.getEyePosition(),actor.getEyePosition().add(actor.getLookAngle().scale(Math.min(8,actor.blockInteractionRange()))),ClipContext.Block.OUTLINE,ClipContext.Fluid.NONE,CollisionContext.of(actor)));if(actual.getType()!=HitResult.Type.BLOCK||!world.getBlockState(actual.getBlockPos()).is(block))continue;var authored=block.trace(actual.getBlockPos(),world.getBlockState(actual.getBlockPos()),actor.getEyePosition(),actor.getEyePosition().add(actor.getLookAngle().scale(Math.min(8,actor.blockInteractionRange()))));if(authored!=null&&authored.slot()==slot)return actual;}throw new AssertionError("No actual player pose for authored slot="+slot+" facing="+facing);}
 static void run(ServerLevel world,NativeProgrammerBlock block,BlockPos base)throws Exception{var rows=new ArrayList<JsonObject>();try(var lines=Files.lines(Path.of(System.getenv("VANDOR_PROGRAMMER_WORLD_RAYS_REFERENCE")))){lines.forEach(line->{var row=JsonParser.parseString(line).getAsJsonObject();if(!row.has("golden"))rows.add(row);});}var actor=new Actor(world);int index=0;for(var facing:Direction.Plane.HORIZONTAL)for(boolean creative:new boolean[]{false,true}){var root=base.east(index++*8);for(int part=0;part<4;part++){var pos=NativeProgrammerBlock.cell(root,facing,part);world.getChunkAt(pos);world.setBlock(pos,block.defaultBlockState().setValue(NativeProgrammerBlock.FACING,facing).setValue(NativeProgrammerBlock.PART,part),3);}var owner=(NativeProgrammerEntity)world.getBlockEntity(root);actor.setGameMode(creative?GameType.CREATIVE:GameType.SURVIVAL);actor.opened=0;actor.containerMenu=actor.inventoryMenu;actor.setShiftKeyDown(false);var hit=aim(actor,world,block,root,facing,1,rows);actor.setItemInHand(InteractionHand.MAIN_HAND,NativeCredentialItems.accessCard(2).copyWithCount(2));need(actor.gameMode.useItemOn(actor,world,actor.getMainHandItem(),InteractionHand.MAIN_HAND,hit).consumesAction()&&actor.getMainHandItem().getCount()==1&&owner.getItem(1).getCount()==1&&actor.opened==0,"actual socket consumes one even Creative");long sequence=owner.visual().sequence();need(actor.gameMode.useItemOn(actor,world,actor.getMainHandItem(),InteractionHand.MAIN_HAND,hit).consumesAction()&&actor.getMainHandItem().getCount()==1&&owner.visual().sequence()==sequence,"occupied socket consumed without mutation");actor.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);need(actor.gameMode.useItemOn(actor,world,actor.getMainHandItem(),InteractionHand.MAIN_HAND,hit).consumesAction()&&actor.getMainHandItem().getCount()==1&&owner.getItem(1).isEmpty(),"actual empty hand returns sole token");hit=aim(actor,world,block,root,facing,2,rows);actor.setItemInHand(InteractionHand.OFF_HAND,NativeCredentialItems.dataChip(2).copyWithCount(2));need(actor.gameMode.useItemOn(actor,world,actor.getOffhandItem(),InteractionHand.OFF_HAND,hit).consumesAction()&&actor.getOffhandItem().getCount()==1&&owner.getItem(2).getCount()==1,"offhand socket exact one owner");actor.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);need(actor.gameMode.useItemOn(actor,world,actor.getOffhandItem(),InteractionHand.OFF_HAND,hit).consumesAction()&&actor.getOffhandItem().getCount()==1&&owner.getItem(2).isEmpty(),"offhand extraction returns token");
   hit=aim(actor,world,block,root,facing,0,rows);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.STICK,2));need(actor.gameMode.useItemOn(actor,world,actor.getMainHandItem(),InteractionHand.MAIN_HAND,hit).consumesAction()&&actor.getMainHandItem().getCount()==2&&owner.getItem(0).isEmpty()&&actor.opened==0,"invalid socket item consumed without opening GUI");hit=aim(actor,world,block,root,facing,-1,rows);need(actor.gameMode.useItemOn(actor,world,actor.getMainHandItem(),InteractionHand.MAIN_HAND,hit).consumesAction()&&actor.opened==1&&actor.containerMenu instanceof NativeProgrammerMenu menu&&menu.tile==owner&&actor.menuPos.equals(root),"ordinary body opens exact dedicated menu");actor.containerMenu=actor.inventoryMenu;actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(VandorLabsBootstrap.CONFIGURIZER.get()));actor.setShiftKeyDown(true);need(block.openConfiguration(actor,world,hit.getBlockPos())&&actor.opened==2&&actor.containerMenu instanceof NativeProgrammerMenu,"shared Configurizer helper chooses same dialog");actor.containerMenu=actor.inventoryMenu;hit=aim(actor,world,block,root,facing,1,rows);need(block.openConfiguration(actor,world,hit.getBlockPos())&&actor.opened==2&&owner.getItem(1).isEmpty(),"Configurator helper preserves pad precedence");actor.setShiftKeyDown(false);actor.setPos(root.getX()+25,root.getY(),root.getZ());need(block.openConfiguration(actor,world,root)&&actor.opened==2,"distant owner cannot open dialog");need(!java.util.concurrent.CompletableFuture.supplyAsync(()->block.openConfiguration(actor,world,root)).join(),"worker activation refused before world lookup");world.removeBlock(root,false);need(!block.openConfiguration(actor,world,root)&&owner.getItem(0).isEmpty(),"stale root cannot activate");}
  System.out.println("[vandorlabs][programmer-interaction] PASS checks="+checks+" facings=4 modes=2 actualGameMode sockets body offhand sharedConfigHelper noClientTransportClaim");}
}
